from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class Traces(SchemaObject):
    sub_type = SchemaField(name='sub_type', optional=True)
    trace_id = SchemaField(name='trace_id', not_null=True)
    nb_reports = SchemaField(name='nb_reports', not_null=True)

    def __init__(self, sub_type, trace_id, nb_reports):
        self.sub_type = sub_type
        self.trace_id = trace_id
        self.nb_reports = nb_reports

        super(Traces, self).__init__()


class GetAllL1StreamingTraceV1(SchemaObject):
    cell_id = SchemaField(name='cell_id', not_null=True)
    output_mode = SchemaField(name='output_mode', not_null=True)
    traces = SchemaField(name='traces', not_null=True, klass=Traces, many=True)
    status = SchemaField(name='status', not_null=True)

    def __init__(self, cell_id, output_mode, traces, status):
        self.cell_id = cell_id
        self.output_mode = output_mode
        self.traces = traces
        self.status = status

        super(GetAllL1StreamingTraceV1, self).__init__()
